//! `ColorConverter::rgbToCMYK` — reverse-engineered from black-box differential
//! testing of /workspace/dataset/test12_executable (164,303 oracle invocations,
//! 0 mismatches; 93,356 distinct CMYK output tuples).
//!
//! Confirmed C++ source shape:
//! ```cpp
//! float max = std::max(std::max(r, g), b);
//! float k = 1.0f - max;
//! if (k == 1) { c = m = y = 0; }          // NOT `max == 0`, NOT `k >= 1`
//! else {
//!     c = (1.0f - r - k) / (1.0f - k);    // i.e. ((1-r)-k) / (1-k)
//!     m = (1.0f - g - k) / (1.0f - k);
//!     y = (1.0f - b - k) / (1.0f - k);
//! }
//! ```
//! All arithmetic is IEEE-754 binary32, round-to-nearest-even, left-to-right,
//! no contraction, no double/extended intermediates.

/// CMYK result. Fields are raw `f32`; no clamping is performed anywhere, so
/// out-of-gamut inputs yield out-of-range / infinite / NaN components.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

/// Exactly `std::max(a, b)` from libstdc++: `(a < b) ? b : a`.
///
/// Returns the FIRST argument on ties (so `max(-0.0, 0.0) == -0.0`) and returns
/// the first argument whenever either operand is NaN (all `<` comparisons are
/// false). Evidence: `(-nan, 0.5, 0.5)` -> cmyk `-nan -nan -nan -nan` (max is
/// the NaN, so k is NaN), whereas `(0.5, nan, 0.5)` -> cmyk `0 nan 0 0.5`
/// (max = 0.5, the NaN loses the reduction and only leaks into `m`).
#[inline]
fn std_max(a: f32, b: f32) -> f32 {
    if a < b { b } else { a }
}

/// `max = std::max(std::max(r, g), b)` — the 3-way reduction used by the library.
#[inline]
fn max3(r: f32, g: f32, b: f32) -> f32 {
    std_max(std_max(r, g), b)
}

/// Convert linear RGB components to CMYK, bit-exactly reproducing the C++ oracle.
///
/// # Pinned details and the inputs that pin them
///
/// * `k = 1.0f32 - max`. A `1 - max` int literal, and a `double` intermediate
///   rounded back to `f32`, are *bitwise identical* for all 2^32 float values of
///   `max` (verified exhaustively), so the choice is unobservable.
///
/// * The guard is `k == 1.0`, **not** `max == 0.0`:
///   `(1e-8, 0, 0)` -> `0 0 0 1`. Here `max = 1e-8 != 0`, but
///   `1.0f - 1e-8f` rounds to exactly `1.0f` (1e-8 < 2^-25), so the guard fires.
///   A `max == 0` guard would divide by `1 - k == 0` and print `-nan -nan -nan 1`.
///   `(2.98023224e-08, 0, 0)` -> `0 0 0 1` (just under 2^-25) vs
///   `(3.1e-8, 0, 0)` -> `0 1 1 1` (just over 2^-25, guard does not fire):
///   the guard boundary sits exactly at the `1.0f - max == 1.0f` rounding
///   threshold, not at `max == 0`.
///
/// * The guard is **not** `k >= 1`: `(-1, -1, -1)` -> `-0 -0 -0 2` and
///   `(-2.6932409e-07, -4.42285057e-07, -3.46639865e-07)` -> `-0 -1 -0.5 1`
///   both have `k > 1` yet still take the division branch.
///   `(k == 1)` and `((1.0 - k) == 0.0)` are provably equivalent for all 2^32
///   floats (verified exhaustively), so that spelling is unobservable.
///
/// * There is a guard at all: `(0, 0, 0)` -> `0 0 0 1`, not `-nan -nan -nan 1`.
///
/// * The guard writes literal `+0.0`, not a sign-carrying zero:
///   `(-1e-8, -1e-8, -1e-8)` -> `0 0 0 1` (prints `0`, not `-0`), even though
///   `max < 0` there.
///
/// * The denominator is `1.0f - k`, **not** `max` (they differ because `k` is
///   itself rounded): `(3.1e-8, 0, 0)` -> `0 1 1 1`, where `1 - k == 2^-24 ==
///   5.96e-8` while `max == 3.1e-8`; dividing by `max` would give `0 1.92273
///   1.92273 1`.
///
/// * The channel numerator is `((1 - x) - k)`, **not** `(1 - (x + k))`:
///   `(1e30, 1, 1)` -> `0 1 1 -1e+30`; the `(1 - (r + k))` grouping yields
///   `c = 1e-30`.
///
/// * It is `(1 - x - k) / (1 - k)`, **not** the algebraically identical
///   `(max - x) / max`: `(1e-7, 1e-8, 1e-9)` -> `0 1 1 1`, while
///   `(max - x) / max` yields `0 0.9 0.99 1`. Likewise not `((1-k) - x) / (1-k)`
///   (yields `0.161139 0.916114 0.991611 1`) and not `1 - x/max`
///   (`(inf, 0.2, 0.3)` -> `-nan -nan -nan -inf`, but `1 - x/max` gives
///   `-nan 1 1 -inf`).
///
/// * It is a true division, not a multiply by a precomputed reciprocal
///   `1.0f / (1.0f - k)`: `(0.970731616, 0.244352102, 0.794469595)` ->
///   `0 0.74828 0.181576 0.0292684`; the reciprocal form gives `m = 0.748281`.
///
/// * No `double` intermediates anywhere in the channels. Full-double evaluation
///   is killed by `(3.1e-8, 0, 0)` (gives `c = 0.479906` instead of `0`);
///   float-numerator-with-double-denominator is killed by
///   `(3.09588604e-19, 24461076, -1.63573056e+17)` -> oracle
///   `1 0 6.68708e+09 -2.44611e+07`, mixed form gives `y = 6.68707e+09`.
///
/// # Non-finite behaviour (all reproduced bit-exactly, incl. NaN sign bits)
///
/// | input                | cmyk output              |
/// |----------------------|--------------------------|
/// | `inf 0.2 0.3`        | `-nan -nan -nan -inf`    |
/// | `-inf 0.2 0.3`       | `inf 0.333333 0 0.7`     |
/// | `nan 0.2 0.3`        | `nan nan nan nan`        |
/// | `inf inf inf`        | `-nan -nan -nan -inf`    |
/// | `-inf -inf -inf`     | `-nan -nan -nan inf`     |
/// | `inf -inf 0.5`       | `-nan -nan -nan -inf`    |
/// | `-nan 0.5 0.5`       | `-nan -nan -nan -nan`    |
/// | `0.5 nan 0.5`        | `0 nan 0 0.5`            |
///
/// The `-nan` results come from `inf - inf` producing the x86 default QNaN
/// (sign bit set); `1.0 - nan` propagates the operand's NaN sign unchanged,
/// which is what native `f32` arithmetic on x86-64 does in Rust as well.
#[inline]
pub fn rgb_to_cmyk(r: f32, g: f32, b: f32) -> Cmyk {
    let max = max3(r, g, b);
    let k = 1.0f32 - max;

    if k == 1.0f32 {
        // Achromatic / black guard. `k` is exactly 1.0f32 here by construction,
        // so writing `k: 1.0` instead is indistinguishable.
        Cmyk { c: 0.0f32, m: 0.0f32, y: 0.0f32, k }
    } else {
        // A shared `den` is bit-identical to repeating `(1.0f - k)` three times.
        let den = 1.0f32 - k;
        Cmyk {
            c: (1.0f32 - r - k) / den,
            m: (1.0f32 - g - k) / den,
            y: (1.0f32 - b - k) / den,
            k,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn bits(v: [f32; 4]) -> [u32; 4] {
        [v[0].to_bits(), v[1].to_bits(), v[2].to_bits(), v[3].to_bits()]
    }

    #[test]
    fn guard_is_k_eq_one_not_max_eq_zero() {
        // (1e-8, 0, 0): max != 0 but 1.0f - max == 1.0f  ->  guard fires.
        let o = rgb_to_cmyk(1e-8, 0.0, 0.0);
        assert_eq!(bits([o.c, o.m, o.y, o.k]), bits([0.0, 0.0, 0.0, 1.0]));
        // Just past the 2^-25 threshold the guard must NOT fire.
        let o = rgb_to_cmyk(3.1e-8, 0.0, 0.0);
        assert_eq!(o.c, 0.0);
        assert_eq!(o.m, 1.0);
        assert_eq!(o.y, 1.0);
    }

    #[test]
    fn guard_writes_positive_zero() {
        // max < 0 yet the guard still fires and must emit +0.0, printing "0".
        let o = rgb_to_cmyk(-1e-8, -1e-8, -1e-8);
        assert_eq!(bits([o.c, o.m, o.y, o.k]), bits([0.0, 0.0, 0.0, 1.0]));
    }

    #[test]
    fn no_k_ge_one_guard() {
        // Oracle: -1 -1 -1  ->  "-0 -0 -0 2"
        let o = rgb_to_cmyk(-1.0, -1.0, -1.0);
        assert_eq!(o.k, 2.0);
        assert!(o.c == 0.0 && o.c.is_sign_negative());
        assert!(o.m == 0.0 && o.m.is_sign_negative());
        assert!(o.y == 0.0 && o.y.is_sign_negative());
    }

    #[test]
    fn not_max_minus_x_over_max() {
        // (max - x)/max would give 0 / 0.9 / 0.99; the real formula gives 0/1/1.
        let o = rgb_to_cmyk(1e-7, 1e-8, 1e-9);
        assert_eq!(o.c, 0.0);
        assert_eq!(o.m, 1.0);
        assert_eq!(o.y, 1.0);
    }

    #[test]
    fn not_one_minus_sum_grouping() {
        // (1 - (r + k)) would give c = 1e-30 here; correct answer is exactly 0.
        let o = rgb_to_cmyk(1e30, 1.0, 1.0);
        assert_eq!(o.c, 0.0);
        assert_eq!(o.k, -1e30);
    }

    #[test]
    fn default_case() {
        // Oracle default args 0.4 0.2 0.8  ->  "0.5 0.75 0 0.2"
        let o = rgb_to_cmyk(0.4, 0.2, 0.8);
        assert_eq!(o.c, 0.5);
        assert_eq!(o.m, 0.75);
        assert_eq!(o.y, 0.0);
        assert_eq!(o.k, 0.2f32);
    }

    #[test]
    fn nonfinite() {
        let o = rgb_to_cmyk(f32::INFINITY, 0.2, 0.3);
        assert!(o.c.is_nan() && o.c.is_sign_negative()); // prints "-nan"
        assert_eq!(o.k, f32::NEG_INFINITY);

        let o = rgb_to_cmyk(f32::NEG_INFINITY, 0.2, 0.3);
        assert_eq!(o.c, f32::INFINITY);
        assert_eq!(o.k, 0.7f32);
        assert_eq!(o.y, 0.0);

        // NaN loses the std::max reduction against 0.5, so only `m` is NaN.
        let o = rgb_to_cmyk(0.5, f32::NAN, 0.5);
        assert_eq!(o.c, 0.0);
        assert!(o.m.is_nan());
        assert_eq!(o.y, 0.0);
        assert_eq!(o.k, 0.5);
    }
}

